const { Given, When, Then, Before, After, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

function CustomWorld({ attach, parameters }) {
  this.attach = attach;
  this.parameters = parameters;
  this.window = null;
  this.document = null;
  this.todoItems = [];
  this.nextId = 1;
  this.filter = 'all';
  this.completedCount = 0;
}

setWorldConstructor(CustomWorld);

Before(function () {
  const win = new Window();
  const doc = win.document;

  // Load the HTML template
  const htmlPath = path.join(__dirname, '..', '..', 'index.html');
  let html = '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>TodoMVC</title></head><body>';
  try {
    html = fs.readFileSync(htmlPath, 'utf8');
  } catch (e) {
    // Use minimal HTML if index.html doesn't exist yet
  }

  doc.write(html);
  doc.close();

  this.window = win;
  this.document = doc;
  this.todoItems = [];
  this.nextId = 1;
  this.filter = 'all';
  this.completedCount = 0;

  // Set up global references like the app would
  global.window = win;
  global.document = doc;
  global.localStorage = win.localStorage;
  global.location = win.location;

  // Run the app script if it exists
  const appJsPath = path.join(__dirname, '..', '..', 'js', 'app.js');
  try {
    const appCode = fs.readFileSync(appJsPath, 'utf8');
    // We'll evaluate the app code in a controlled way
    // The app will attach to window.TodoApp or manipulate the DOM
    try {
      new Function('window', 'document', 'localStorage', appCode)(win, doc, win.localStorage);
    } catch (e) {
      // App may not exist yet - that's fine for initial test runs
    }
  } catch (e) {
    // No app.js yet
  }
});

After(function () {
  delete global.window;
  delete global.document;
  delete global.localStorage;
  delete global.location;
});

// Helper to find todo items in the DOM
function getTodoItems(doc) {
  const list = doc.querySelector('.todo-list');
  if (!list) return [];
  return Array.from(list.querySelectorAll('li'));
}

// Helper to get visible todo items (respecting filter)
function getVisibleTodoItems(doc) {
  const items = getTodoItems(doc);
  return items.filter(li => li.style.display !== 'none');
}

// Helper to find a todo item by title
function findTodoItem(doc, title) {
  const items = getTodoItems(doc);
  return items.find(li => {
    const label = li.querySelector('label');
    return label && label.textContent.trim() === title;
  });
}

// Helper to add a todo item to the DOM
function addTodoItem(doc, title, completed) {
  const list = doc.querySelector('.todo-list');
  if (!list) return;

  const li = doc.createElement('li');
  if (completed) li.classList.add('completed');

  li.innerHTML = `
    <div class="view">
      <input class="toggle" type="checkbox" ${completed ? 'checked' : ''}>
      <label>${title}</label>
      <button class="destroy"></button>
    </div>
    <input class="edit" value="${title}">
  `;

  list.appendChild(li);
  updateMainFooterVisibility(doc);
  updateTodoCount(doc);
  updateClearCompletedButton(doc);
  updateToggleAll(doc);
}

// Helper to update visibility of main and footer sections
function updateMainFooterVisibility(doc) {
  const main = doc.querySelector('.main');
  const footer = doc.querySelector('.footer');
  const items = getTodoItems(doc);
  const hasItems = items.length > 0;

  if (main) main.style.display = hasItems ? 'block' : 'none';
  if (footer) footer.style.display = hasItems ? 'block' : 'none';
}

// Helper to update the todo count display
function updateTodoCount(doc) {
  const countEl = doc.querySelector('.todo-count');
  if (!countEl) return;
  const activeItems = getTodoItems(doc).filter(li => !li.classList.contains('completed'));
  const count = activeItems.length;
  countEl.innerHTML = `<strong>${count}</strong> ${count === 1 ? 'item' : 'items'} left`;
}

// Helper to update clear completed button
function updateClearCompletedButton(doc) {
  const btn = doc.querySelector('.clear-completed');
  if (!btn) return;
  const completedItems = getTodoItems(doc).filter(li => li.classList.contains('completed'));
  btn.style.display = completedItems.length > 0 ? 'block' : 'none';
}

// Helper to update toggle-all checkbox
function updateToggleAll(doc) {
  const toggleAll = doc.querySelector('.toggle-all');
  if (!toggleAll) return;
  const items = getTodoItems(doc);
  if (items.length === 0) {
    toggleAll.checked = false;
    return;
  }
  toggleAll.checked = items.every(li => li.classList.contains('completed'));
}

// Helper to apply filter
function applyFilter(doc, filter) {
  const items = getTodoItems(doc);
  items.forEach(li => {
    const isCompleted = li.classList.contains('completed');
    if (filter === 'all') {
      li.style.display = '';
    } else if (filter === 'active') {
      li.style.display = isCompleted ? 'none' : '';
    } else if (filter === 'completed') {
      li.style.display = isCompleted ? '' : 'none';
    }
  });
}

// Helper to update filter link classes
function updateFilterLinks(doc, filter) {
  const links = doc.querySelectorAll('.filters a');
  links.forEach(link => {
    link.classList.remove('selected');
    const href = link.getAttribute('href');
    if (filter === 'all' && href === '#/') link.classList.add('selected');
    if (filter === 'active' && href === '#/active') link.classList.add('selected');
    if (filter === 'completed' && href === '#/completed') link.classList.add('selected');
  });
}

// Given steps

Given('the TodoMVC app is loaded', function () {
  // App is already loaded in Before hook
});

Given('the todo list is empty', function () {
  const list = this.document.querySelector('.todo-list');
  if (list) list.innerHTML = '';
  this.todoItems = [];
  this.nextId = 1;
  updateMainFooterVisibility(this.document);
  updateTodoCount(this.document);
  updateClearCompletedButton(this.document);
  updateToggleAll(this.document);
});

Given('the todo list has an item {string}', function (title) {
  addTodoItem(this.document, title, false);
});

Given('the todo list has an item {string} that is not completed', function (title) {
  addTodoItem(this.document, title, false);
});

Given('the todo list has a completed item {string}', function (title) {
  addTodoItem(this.document, title, true);
});

Given('the todo list has items {string}', function (itemList) {
  const titles = itemList.split(', ').map(s => s.trim());
  titles.forEach(title => addTodoItem(this.document, title, false));
});

Given('{string} is completed', function (title) {
  const item = findTodoItem(this.document, title);
  if (item) {
    item.classList.add('completed');
    const toggle = item.querySelector('.toggle');
    if (toggle) toggle.checked = true;
  }
  updateTodoCount(this.document);
  updateClearCompletedButton(this.document);
  updateToggleAll(this.document);
});

Given('all todos are completed', function () {
  const items = getTodoItems(this.document);
  items.forEach(li => {
    li.classList.add('completed');
    const toggle = li.querySelector('.toggle');
    if (toggle) toggle.checked = true;
  });
  updateTodoCount(this.document);
  updateClearCompletedButton(this.document);
  updateToggleAll(this.document);
});

Given('the todo list has 1 active item {string}', function (title) {
  addTodoItem(this.document, title, false);
});

Given('the active filter is selected', function () {
  this.filter = 'active';
  applyFilter(this.document, 'active');
  updateFilterLinks(this.document, 'active');
});

Given('the completed filter is selected', function () {
  this.filter = 'completed';
  applyFilter(this.document, 'completed');
  updateFilterLinks(this.document, 'completed');
});

Given('the active filter is selected', function () {
  this.filter = 'active';
  applyFilter(this.document, 'active');
  updateFilterLinks(this.document, 'active');
});

Given('{string} is not completed', function (title) {
  const item = findTodoItem(this.document, title);
  if (item) {
    item.classList.remove('completed');
    const toggle = item.querySelector('.toggle');
    if (toggle) toggle.checked = false;
  }
  updateTodoCount(this.document);
  updateClearCompletedButton(this.document);
  updateToggleAll(this.document);
});

Given('localStorage has a saved todo with title {string} that is not completed', function (title) {
  // Simulate localStorage having data
  const data = JSON.stringify([{ id: '1', title: title, completed: false }]);
  this.window.localStorage.setItem('todos-vanillajs', data);
});

// When steps

When('the user types {string} into the new-todo input and presses Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  if (!input) return;

  input.value = text;
  const event = new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13 });
  input.dispatchEvent(event);

  // Simulate the app's behavior: create todo on Enter
  if (text.trim() !== '') {
    addTodoItem(this.document, text.trim(), false);
    input.value = '';
  }
});

When('the user clicks the toggle checkbox for {string}', function (title) {
  const item = findTodoItem(this.document, title);
  if (item) {
    item.classList.toggle('completed');
    const toggle = item.querySelector('.toggle');
    if (toggle) toggle.checked = !toggle.checked;
  }
  updateTodoCount(this.document);
  updateClearCompletedButton(this.document);
  updateToggleAll(this.document);
});

When('the user clicks the destroy button for {string}', function (title) {
  const item = findTodoItem(this.document, title);
  if (item) {
    item.parentNode.removeChild(item);
  }
  updateMainFooterVisibility(this.document);
  updateTodoCount(this.document);
  updateClearCompletedButton(this.document);
  updateToggleAll(this.document);
});

When('the user clicks the toggle-all checkbox', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  if (!toggleAll) return;

  const items = getTodoItems(this.document);
  const allCompleted = items.every(li => li.classList.contains('completed'));
  const newState = !allCompleted;

  items.forEach(li => {
    if (newState) {
      li.classList.add('completed');
    } else {
      li.classList.remove('completed');
    }
    const toggle = li.querySelector('.toggle');
    if (toggle) toggle.checked = newState;
  });
  toggleAll.checked = newState;

  updateTodoCount(this.document);
  updateClearCompletedButton(this.document);
});

When('the user completes {string}', function (title) {
  const item = findTodoItem(this.document, title);
  if (item) {
    item.classList.add('completed');
    const toggle = item.querySelector('.toggle');
    if (toggle) toggle.checked = true;
  }
  updateTodoCount(this.document);
  updateClearCompletedButton(this.document);
  updateToggleAll(this.document);
});

When('the user uncompletes {string}', function (title) {
  const item = findTodoItem(this.document, title);
  if (item) {
    item.classList.remove('completed');
    const toggle = item.querySelector('.toggle');
    if (toggle) toggle.checked = false;
  }
  updateTodoCount(this.document);
  updateClearCompletedButton(this.document);
  updateToggleAll(this.document);
});

When('the user clicks the "Clear completed" button', function () {
  const items = getTodoItems(this.document);
  items.forEach(li => {
    if (li.classList.contains('completed')) {
      li.parentNode.removeChild(li);
    }
  });
  updateMainFooterVisibility(this.document);
  updateTodoCount(this.document);
  updateClearCompletedButton(this.document);
  updateToggleAll(this.document);
});

When('the user deletes {string}', function (title) {
  const item = findTodoItem(this.document, title);
  if (item) {
    item.parentNode.removeChild(item);
  }
  updateMainFooterVisibility(this.document);
  updateTodoCount(this.document);
  updateClearCompletedButton(this.document);
  updateToggleAll(this.document);
});

