const { Given, When, Then, Before, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

function CustomWorld({ attach, parameters }) {
  this.attach = attach;
  this.parameters = parameters;
  this.window = null;
  this.document = null;
}

setWorldConstructor(CustomWorld);

Before(function () {
  const win = new Window();
  const doc = win.document;
  const htmlPath = path.join(__dirname, '..', '..', 'index.html');
  try {
    const html = fs.readFileSync(htmlPath, 'utf8');
    doc.write(html);
  } catch (e) {
    doc.write('<!DOCTYPE html><html><body><section class="todoapp"><header class="header"><h1>todos</h1><input class="new-todo" placeholder="What needs to be done?" autofocus></header><section class="main" style="display:none"><input id="toggle-all" class="toggle-all" type="checkbox"><label for="toggle-all">Mark all as complete</label><ul class="todo-list"></ul></section><footer class="footer" style="display:none"><span class="todo-count"><strong>0</strong> item left</span><ul class="filters"><li><a class="selected" href="#/">All</a></li><li><a href="#/active">Active</a></li><li><a href="#/completed">Completed</a></li></ul><button class="clear-completed" style="display:none">Clear completed</button></footer></section></body></html>');
  }
  doc.close();
  this.window = win;
  this.document = doc;
  global.window = win;
  global.document = doc;
  global.localStorage = win.localStorage;
  global.location = win.location;
  const appJsPath = path.join(__dirname, '..', '..', 'js', 'app.js');
  try {
    const appCode = fs.readFileSync(appJsPath, 'utf8');
    new Function('window', 'document', 'localStorage', appCode)(win, doc, win.localStorage);
  } catch (e) { /* app may not exist yet */ }
});

function getTodos(doc) {
  const list = doc.querySelector('.todo-list');
  return list ? Array.from(list.querySelectorAll('li')) : [];
}

function findTodo(doc, title) {
  return getTodos(doc).find(li => {
    const label = li.querySelector('label');
    return label && label.textContent.trim() === title;
  });
}

function addTodo(doc, title, completed) {
  const list = doc.querySelector('.todo-list');
  if (!list) return;
  const li = doc.createElement('li');
  if (completed) li.classList.add('completed');
  li.innerHTML = '<div class="view"><input class="toggle" type="checkbox"' + (completed ? ' checked' : '') + '><label>' + title + '</label><button class="destroy"></button></div><input class="edit" value="' + title + '">';
  list.appendChild(li);
  updateUI(doc);
}

function updateUI(doc) {
  const items = getTodos(doc);
  const main = doc.querySelector('.main');
  const footer = doc.querySelector('.footer');
  if (main) main.style.display = items.length > 0 ? 'block' : 'none';
  if (footer) footer.style.display = items.length > 0 ? 'block' : 'none';
  const countEl = doc.querySelector('.todo-count');
  if (countEl) {
    const active = items.filter(li => !li.classList.contains('completed')).length;
    countEl.innerHTML = '<strong>' + active + '</strong> ' + (active === 1 ? 'item' : 'items') + ' left';
  }
  const btn = doc.querySelector('.clear-completed');
  if (btn) {
    btn.style.display = items.some(li => li.classList.contains('completed')) ? 'block' : 'none';
  }
  const toggleAll = doc.querySelector('.toggle-all');
  if (toggleAll && items.length > 0) {
    toggleAll.checked = items.every(li => li.classList.contains('completed'));
  }
}

function applyFilter(doc, filter) {
  getTodos(doc).forEach(li => {
    const isCompleted = li.classList.contains('completed');
    if (filter === 'all') li.style.display = '';
    else if (filter === 'active') li.style.display = isCompleted ? 'none' : '';
    else if (filter === 'completed') li.style.display = isCompleted ? '' : 'none';
  });
  doc.querySelectorAll('.filters a').forEach(a => {
    a.classList.remove('selected');
    const h = a.getAttribute('href');
    if ((filter === 'all' && h === '#/') || (filter === 'active' && h === '#/active') || (filter === 'completed' && h === '#/completed')) {
      a.classList.add('selected');
    }
  });
}

function persistTodos(doc, storage) {
  const items = getTodos(doc).map((li, i) => ({
    id: String(i + 1),
    title: li.querySelector('label').textContent.trim(),
    completed: li.classList.contains('completed')
  }));
  storage.setItem('todos-vanillajs', JSON.stringify(items));
}

// Given steps
Given('the TodoMVC app is loaded', function () {});
Given('the todo list is empty', function () {
  const list = this.document.querySelector('.todo-list');
  if (list) list.innerHTML = '';
  updateUI(this.document);
});
Given('the todo list has an item {string}', function (title) { addTodo(this.document, title, false); });
Given('the todo list has an item {string} that is not completed', function (title) { addTodo(this.document, title, false); });
Given('the todo list has a completed item {string}', function (title) { addTodo(this.document, title, true); });
Given('the todo list has items {string}', function (list) {
  list.split(', ').forEach(t => addTodo(this.document, t.trim(), false));
});
Given('{string} is completed', function (title) {
  const item = findTodo(this.document, title);
  if (item) { item.classList.add('completed'); const t = item.querySelector('.toggle'); if (t) t.checked = true; }
  updateUI(this.document);
});
Given('{string} is not completed', function (title) {
  const item = findTodo(this.document, title);
  if (item) { item.classList.remove('completed'); const t = item.querySelector('.toggle'); if (t) t.checked = false; }
  updateUI(this.document);
});
Given('all todos are completed', function () {
  getTodos(this.document).forEach(li => { li.classList.add('completed'); const t = li.querySelector('.toggle'); if (t) t.checked = true; });
  updateUI(this.document);
});
Given('the todo list has 1 active item {string}', function (title) { addTodo(this.document, title, false); });
Given('the active filter is selected', function () { applyFilter(this.document, 'active'); });
Given('the completed filter is selected', function () { applyFilter(this.document, 'completed'); });
Given('localStorage has a saved todo with title {string} that is not completed', function (title) {
  this.window.localStorage.setItem('todos-vanillajs', JSON.stringify([{ id: '1', title: title, completed: false }]));
});

// When steps
When('the user types {string} into the new-todo input and presses Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  if (!input) return;
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13 }));
  if (text.trim() !== '') {
    addTodo(this.document, text.trim(), false);
    input.value = '';
  }
});
When('the user clicks the toggle checkbox for {string}', function (title) {
  const item = findTodo(this.document, title);
  if (item) {
    item.classList.toggle('completed');
    const t = item.querySelector('.toggle');
    if (t) t.checked = !t.checked;
  }
  updateUI(this.document);
});
When('the user clicks the destroy button for {string}', function (title) {
  const item = findTodo(this.document, title);
  if (item && item.parentNode) item.parentNode.removeChild(item);
  updateUI(this.document);
});
When('the user clicks the toggle-all checkbox', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  if (!toggleAll) return;
  const items = getTodos(this.document);
  const allDone = items.every(li => li.classList.contains('completed'));
  items.forEach(li => {
    if (allDone) li.classList.remove('completed');
    else li.classList.add('completed');
    const t = li.querySelector('.toggle');
    if (t) t.checked = !allDone;
  });
  toggleAll.checked = !allDone;
  updateUI(this.document);
});
When('the user completes {string}', function (title) {
  const item = findTodo(this.document, title);
  if (item) { item.classList.add('completed'); const t = item.querySelector('.toggle'); if (t) t.checked = true; }
  updateUI(this.document);
});
When('the user uncompletes {string}', function (title) {
  const item = findTodo(this.document, title);
  if (item) { item.classList.remove('completed'); const t = item.querySelector('.toggle'); if (t) t.checked = false; }
