(function (window, document, localStorage) {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-vanillajs';

  var todoApp = {
    todos: [],
    filter: 'all',

    init: function () {
      this.bindEvents();
      this.loadFromStorage();
      this.render();
      this.setRoute();
    },

    bindEvents: function () {
      var self = this;
      var newTodo = document.querySelector('.new-todo');
      var toggleAll = document.querySelector('.toggle-all');
      var clearBtn = document.querySelector('.clear-completed');
      var filters = document.querySelectorAll('.filters a');

      newTodo.addEventListener('keydown', function (e) {
        if (e.keyCode === ENTER_KEY) {
          self.addTodo(this.value);
        }
      });

      toggleAll.addEventListener('change', function () {
        self.toggleAll(this.checked);
      });

      clearBtn.addEventListener('click', function () {
        self.clearCompleted();
      });

      filters.forEach(function (a) {
        a.addEventListener('click', function (e) {
          e.preventDefault();
          var hash = this.getAttribute('href').replace('#/', '') || 'all';
          self.setFilter(hash);
        });
      });

      document.querySelector('.todo-list').addEventListener('click', function (e) {
        var target = e.target;
        var li = target.closest('li');
        if (!li) return;
        var title = li.querySelector('label').textContent.trim();

        if (target.classList.contains('toggle')) {
          self.toggleComplete(title);
        } else if (target.classList.contains('destroy')) {
          self.deleteTodo(title);
        }
      });

      document.querySelector('.todo-list').addEventListener('dblclick', function (e) {
        var target = e.target;
        if (target.tagName === 'LABEL') {
          var li = target.closest('li');
          if (li) {
            li.classList.add('editing');
            var editInput = li.querySelector('.edit');
            editInput.value = li.querySelector('label').textContent.trim();
            editInput.focus();
          }
        }
      });

      document.querySelector('.todo-list').addEventListener('keydown', function (e) {
        if (e.keyCode === ENTER_KEY || e.keyCode === ESCAPE_KEY) {
          var editInput = e.target;
          if (!editInput.classList.contains('edit')) return;
          var li = editInput.closest('li');
          if (!li) return;

          if (e.keyCode === ESCAPE_KEY) {
            li.classList.remove('editing');
          } else {
            self.saveEdit(li, editInput.value);
          }
        }
      });

      document.querySelector('.todo-list').addEventListener('blur', function (e) {
        var editInput = e.target;
        if (!editInput.classList.contains('edit')) return;
        var li = editInput.closest('li');
        if (!li) return;
        self.saveEdit(li, editInput.value);
      }, true);

      window.addEventListener('hashchange', function () {
        self.setRoute();
      });
    },

    addTodo: function (value) {
      value = value.trim();
      if (value === '') return;
      this.todos.push({
        id: String(Date.now()),
        title: value,
        completed: false
      });
      document.querySelector('.new-todo').value = '';
      this.saveToStorage();
      this.render();
    },

    toggleComplete: function (title) {
      this.todos.forEach(function (t) {
        if (t.title === title) {
          t.completed = !t.completed;
        }
      });
      this.saveToStorage();
      this.render();
    },

    deleteTodo: function (title) {
      this.todos = this.todos.filter(function (t) {
        return t.title !== title;
      });
      this.saveToStorage();
      this.render();
    },

    toggleAll: function (checked) {
      this.todos.forEach(function (t) {
        t.completed = checked;
      });
      this.saveToStorage();
      this.render();
    },

    clearCompleted: function () {
      this.todos = this.todos.filter(function (t) {
        return !t.completed;
      });
      this.saveToStorage();
      this.render();
    },

    saveEdit: function (li, value) {
      value = value.trim();
      var title = li.querySelector('label').textContent.trim();

      if (value === '') {
        this.deleteTodo(title);
      } else {
        this.todos.forEach(function (t) {
          if (t.title === title) {
            t.title = value;
          }
        });
        this.saveToStorage();
      }
      li.classList.remove('editing');
      this.render();
    },

    setFilter: function (filter) {
      this.filter = filter;
      this.saveToStorage();
      this.render();
    },

    setRoute: function () {
      var hash = window.location.hash.replace('#/', '') || 'all';
      this.setFilter(hash);
    },

    getFilteredTodos: function () {
      var self = this;
      return this.todos.filter(function (t) {
        if (self.filter === 'active') return !t.completed;
        if (self.filter === 'completed') return t.completed;
        return true;
      });
    },

    loadFromStorage: function () {
      try {
        var data = localStorage.getItem(STORAGE_KEY);
        if (data) {
          this.todos = JSON.parse(data);
          this.filter = 'all';
        }
      } catch (e) {}
    },

    saveToStorage: function () {
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(this.todos));
      } catch (e) {}
    },

    render: function () {
      var list = document.querySelector('.todo-list');
      var main = document.querySelector('.main');
      var footer = document.querySelector('.footer');
      var countEl = document.querySelector('.todo-count');
      var clearBtn = document.querySelector('.clear-completed');
      var toggleAll = document.querySelector('.toggle-all');
      var filters = document.querySelectorAll('.filters a');

      var filtered = this.getFilteredTodos();
      var activeCount = this.todos.filter(function (t) { return !t.completed; }).length;
      var completedCount = this.todos.length - activeCount;

      list.innerHTML = '';
      filtered.forEach(function (todo) {
        var li = document.createElement('li');
        if (todo.completed) li.classList.add('completed');
        li.innerHTML = '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + todo.title + '</label>' +
          '<button class="destroy"></button>' +
          '</div>' +
          '<input class="edit" value="' + todo.title + '">';
        list.appendChild(li);
      });

      main.style.display = this.todos.length > 0 ? 'block' : 'none';
      footer.style.display = this.todos.length > 0 ? 'block' : 'none';

      countEl.innerHTML = '<strong>' + activeCount + '</strong> ' +
        (activeCount === 1 ? 'item' : 'items') + ' left';

      clearBtn.style.display = completedCount > 0 ? 'block' : 'none';

      toggleAll.checked = this.todos.length > 0 && activeCount === 0;

      filters.forEach(function (a) {
        a.classList.remove('selected');
        var href = a.getAttribute('href').replace('#/', '') || 'all';
        if (href === self.filter) {
          a.classList.add('selected');
        }
      });
    }
  };

  var self = todoApp;
  todoApp.init();
})(window, document, localStorage);

